 <section id="landing-questions" class="landing-questions"><div class="questions-heading"><h2>\u0412\u043E\u043F\u0440\u043E\u0441\u044B \u043E\u0431 \u041E\u043F\u0442\u0438\u043C\u0435</h2></div><div class="questions-list">${[["\u041A\u043E\u043C\u0443 \u043F\u043E\u0434\u043E\u0439\u0434\u0451\u0442 \u041E\u043F\u0442\u0438\u043C\u0430?","\u041A\u043E\u043C\u043F\u0430\u043D\u0438\u044F\u043C, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u043D\u0443\u0436\u043D\u044B \u043D\u0435\u0431\u043E\u043B\u044C\u0448\u0438\u0435 \u043F\u0430\u0440\u0442\u0438\u0438 \u043D\u0430 \u043E\u043F\u0442\u043E\u0432\u044B\u0445 \u0443\u0441\u043B\u043E\u0432\u0438\u044F\u0445. \u041F\u043E\u043A\u0443\u043F\u0430\u0442\u0435\u043B\u0438 \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u044F\u044E\u0442 \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B\u0435 \u043F\u043E\u0442\u0440\u0435\u0431\u043D\u043E\u0441\u0442\u0438, \u0430 \u043F\u043E\u0441\u0442\u0430\u0432\u0449\u0438\u043A\u0438 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u044E\u0442 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0434\u043B\u044F \u043E\u0431\u0449\u0435\u0433\u043E \u043E\u0431\u044A\u0451\u043C\u0430."],["\u041C\u043E\u0436\u043D\u043E \u043B\u0438 \u0438 \u0437\u0430\u043A\u0443\u043F\u0430\u0442\u044C, \u0438 \u043F\u0440\u043E\u0434\u0430\u0432\u0430\u0442\u044C?","\u0414\u0430. \u041E\u0434\u043D\u0430 \u043F\u043E\u0447\u0442\u0430 \u0434\u0430\u0451\u0442 \u0434\u043E\u0441\u0442\u0443\u043F \u043A \u0434\u0432\u0443\u043C \u0431\u0438\u0437\u043D\u0435\u0441-\u043F\u0440\u043E\u0444\u0438\u043B\u044F\u043C \u2014 \u0434\u043B\u044F \u0437\u0430\u043A\u0443\u043F\u043E\u043A \u0438 \u043F\u0440\u043E\u0434\u0430\u0436. \u0423 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438 \u0441\u0432\u043E\u0438 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435, \u0440\u0435\u043A\u0432\u0438\u0437\u0438\u0442\u044B, \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u044B \u0438 \u0434\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0431\u0438\u043D\u0435\u0442\u0430."],["\u041D\u0443\u0436\u043D\u043E \u043B\u0438 \u0432\u044B\u043A\u0443\u043F\u0430\u0442\u044C \u0432\u0441\u044E \u043F\u0430\u0440\u0442\u0438\u044E?","\u0412\u044B \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0432\u043E\u0439 \u043E\u0431\u044A\u0451\u043C \u0441 \u0443\u0447\u0451\u0442\u043E\u043C \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0437\u0430\u043A\u0430\u0437\u0430 \u0438 \u0448\u0430\u0433\u0430 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u043F\u043E\u0441\u0442\u0430\u0432\u0449\u0438\u043A\u0430. \u0414\u043B\u044F \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F \u043E\u043F\u0442\u043E\u0432\u043E\u0433\u043E \u043F\u043E\u0440\u043E\u0433\u0430 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0431\u044A\u0451\u043C\u044B \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432 \u0433\u0440\u0443\u043F\u043F\u044B."],["\u041A\u0430\u043A \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043A\u043E\u043C\u0438\u0441\u0441\u0438\u044F?","\u041A\u043E\u043C\u0438\u0441\u0441\u0438\u044F \u041E\u043F\u0442\u0438\u043C\u044B \u2014 3% \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u044D\u043A\u043E\u043D\u043E\u043C\u0438\u0438. \u0418\u0441\u0445\u043E\u0434\u043D\u0430\u044F \u0446\u0435\u043D\u0430 \u0438 \u0441\u043E\u0441\u0442\u0430\u0432 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u044B\u0442\u044C \u0438\u0437\u0432\u0435\u0441\u0442\u043D\u044B: \u0431\u0435\u0437 \u043D\u0438\u0445 \u043D\u0435\u043B\u044C\u0437\u044F \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u044D\u043A\u043E\u043D\u043E\u043C\u0438\u044E. \u0420\u0430\u0441\u0447\u0451\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0434\u043E \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u0438\u044F \u0437\u0430\u043A\u0430\u0437\u0430."],["\u0423 \u0432\u0441\u0435\u0445 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432 \u0431\u0443\u0434\u0443\u0442 \u043E\u0431\u0449\u0438\u0435 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u044B?","\u041D\u0435\u0442. \u0423 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438 \u0441\u0432\u043E\u0439 \u0437\u0430\u043A\u0430\u0437, \u0440\u0435\u043A\u0432\u0438\u0437\u0438\u0442\u044B \u0438 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u044B. \u041E\u0431\u0449\u0438\u043C\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0437\u0430\u043A\u0443\u043F\u043A\u0438 \u0438 \u043E\u0431\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0435 \u0433\u0440\u0443\u043F\u043F\u044B."]].map(([e,t])=>`<details><summary>${e}<span>${c("down",17)}</span></summary><p>${t}</p></details>`).join("")}</div></section>
